#!/usr/bin/env python
"""Render / verify / publish the ``CASE-FVM-DAMBREAK-STOKER-HIRES`` report.

The numeric content of ``REPORT.md`` lives in a single marked block::

    <!-- HIRES-DATA:BEGIN (generated by publish_report.py, do not edit by hand) -->
    ...
    <!-- HIRES-DATA:END -->

Everything inside it is rendered from
``src/tensorfvm/verification/artifacts/shallow-water-dam-break/hires.json``
(produced by ``scripts/run_shallow_water_dam_break_hires.py``) plus the analytic
reference functions in ``tensorfvm.shallow_water.exact``, so it cannot drift
away from the measurement.  The prose outside the block carries *no* measured
number -- ``tests/test_dambreak_hires_docs.py`` enforces both halves of that
rule (block freshness **and** absence of hand-written percentages).

Usage::

    # regenerate the data block in REPORT.md (idempotent) and print a summary
    PYTHONPATH=src python docs/case-fvm-dambreak-stoker-hires/publish_report.py

    # drift gate: fail if the committed block is stale
    PYTHONPATH=src python docs/case-fvm-dambreak-stoker-hires/publish_report.py --check

    # show the block on stdout, write nothing
    PYTHONPATH=src python docs/case-fvm-dambreak-stoker-hires/publish_report.py --stdout

    # publish to the platform (:8001) with the rendered block as the report body
    PYTHONPATH=src python docs/case-fvm-dambreak-stoker-hires/publish_report.py \
        --publish --mission-id 23156
"""

from __future__ import annotations

import argparse
import base64
import json
import os
import sys
import urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "src"))

from tensorfvm.shallow_water.dam_break import (  # noqa: E402
    PLATEAU_THRESH_MAX_DECADES,
    RITTER_DRY,
    STOKER_WET,
)
from tensorfvm.shallow_water.exact import (  # noqa: E402
    ritter_front_position,
    stoker_constant_state,
    t_star_to_time,
)

HERE = Path(__file__).resolve().parent
ARTIFACT = (ROOT / "src/tensorfvm/verification/artifacts/shallow-water-dam-break"
            / "hires.json")
REPORT = HERE / "REPORT.md"
CONVERGENCE_FIG = HERE / "hires_convergence.png"
PROFILE_FIG = HERE / "profiles.png"
BEGIN = "<!-- HIRES-DATA:BEGIN (generated by publish_report.py, do not edit by hand) -->"
END = "<!-- HIRES-DATA:END -->"

#: the anchor's acceptance tolerance (pool contract); the artefact must agree
ANCHOR_TOLERANCE = 0.05
#: report-side acceptance question required by the mission template
STRICT_TOLERANCE = 0.03

BASE = os.environ.get("TENSOR_API_BASE", "http://127.0.0.1:8001/api/v1").rstrip("/")
if BASE.endswith("/api/v1"):
    BASE = BASE[: -len("/api/v1")]
USER = os.environ.get("TENSOR_AGENT_USER", "agent")
PASS = os.environ.get("TENSOR_AGENT_PASS", "agent")


# --------------------------------------------------------------------------- #
# artefact loading + contract checks (refuse to render a stale/contradictory
# payload: the report is only as trustworthy as these guards)
# --------------------------------------------------------------------------- #
def load_payload(path: Path = ARTIFACT) -> dict:
    payload = json.loads(Path(path).read_text())
    for key in ("meta", "cases"):
        if key not in payload:
            raise SystemExit(f"{path}: missing '{key}'")
    meta = payload["meta"]
    for key in ("resolutions", "tolerance", "floor_ratio_rule",
                "min_grids_for_order", "command", "generated_at", "git_commit"):
        if key not in meta:
            raise SystemExit(f"{path}: meta missing '{key}'")
    if abs(float(meta["tolerance"]) - ANCHOR_TOLERANCE) > 0.0:
        raise SystemExit(f"{path}: tolerance {meta['tolerance']} != anchor "
                         f"{ANCHOR_TOLERANCE}")
    for key in (RITTER_DRY.key, STOKER_WET.key):
        case = payload["cases"].get(key)
        if case is None:
            raise SystemExit(f"{path}: missing case '{key}'")
        if [r["n"] for r in case["rows"]] != list(meta["resolutions"]):
            raise SystemExit(f"{path}: {key} rows do not match meta resolutions")
        for r in case["rows"]:
            for field in ("dx", "depth_l1", "front_series", "verdict_failing",
                          "verdict_all_pass"):
                if field not in r:
                    raise SystemExit(f"{path}: {key} n={r['n']} missing {field}")
    wet = payload["cases"][STOKER_WET.key]
    for field in ("fan_over_jump_by_grid", "thresh_frac_ladder_used",
                  "cut_bounded_untightened", "plateau_cut_frac"):
        if field not in wet:
            raise SystemExit(f"{path}: stoker-wet summary missing '{field}' "
                             "(re-run the study script)")
    return payload


# --------------------------------------------------------------------------- #
# formatting helpers -- one place, so the whole block is consistent
# --------------------------------------------------------------------------- #
def _pct(x, digits: int = 3) -> str:
    return "—" if x is None else f"{100.0 * x:.{digits}f} %"


def _num(x, digits: int = 4) -> str:
    return "—" if x is None else f"{x:.{digits}f}"


def _order(x) -> str:
    return "—" if x is None else f"{x:.3f}"


def _ratios(decay: dict) -> str:
    return ", ".join(f"{r['ratio']:.3f}" for r in decay["all_ratios"])


def _monotone(vals) -> bool:
    vals = [v for v in vals if v is not None]
    return all(b <= a for a, b in zip(vals, vals[1:]))


def _row_by_n(case: dict, n: int) -> dict:
    for r in case["rows"]:
        if r["n"] == n:
            return r
    raise KeyError(n)


def _yes(flag: bool) -> str:
    return "是" if flag else "**否**"


# --------------------------------------------------------------------------- #
# the rendered block
# --------------------------------------------------------------------------- #
def render_block(payload: dict) -> str:
    """Every number in the report, rendered from the artefact."""
    meta = payload["meta"]
    dry = payload["cases"][RITTER_DRY.key]
    wet = payload["cases"][STOKER_WET.key]
    res = list(meta["resolutions"])
    n_lo, n_hi = res[0], res[-1]
    tol = meta["tolerance"]

    t_end = t_star_to_time(RITTER_DRY.t_star_end, RITTER_DRY.h0, RITTER_DRY.gravity)
    x_ritter = ritter_front_position(t_end, RITTER_DRY.h0, RITTER_DRY.gravity,
                                     x_dam=RITTER_DRY.x_dam)
    st = stoker_constant_state(STOKER_WET.h0, STOKER_WET.h1, STOKER_WET.gravity)
    x_shock = STOKER_WET.x_dam + st["shock_speed"] * t_end

    dry_lo, dry_hi = _row_by_n(dry, n_lo), _row_by_n(dry, n_hi)
    wet_lo, wet_hi = _row_by_n(wet, n_lo), _row_by_n(wet, n_hi)
    ladder_hi = wet_hi.get("bore_attempts") or []
    decades_used = 0 if not ladder_hi else int(ladder_hi[-1]["decade"])
    decades_left = PLATEAU_THRESH_MAX_DECADES - decades_used
    fan_first = wet.get("fan_over_jump_first_below_cut")
    cut = wet.get("plateau_cut_frac", meta.get("plateau_cut_frac"))
    flat_flag = wet.get("plateau_flat_fraction", meta.get("plateau_flat_fraction"))
    untightened_ok = None if not ladder_hi else bool(ladder_hi[0]["bounded"])
    cell_ratio = (wet_hi["bore_x_cell_error"] / _row_by_n(wet, res[-2])["bore_x_cell_error"]
                  if _row_by_n(wet, res[-2])["bore_x_cell_error"] else float("nan"))
    all_guard_pass = all(r["verdict_all_pass"] for r in dry["rows"] + wet["rows"])
    series_worst = max(dry["series_max_over_accepted"], wet["series_max_over_accepted"])
    at_floor = bool(dry["series_decay"]["at_floor"] or wet["series_decay"]["at_floor"])

    L: list[str] = []
    a = L.append
    a(BEGIN)
    a("")
    a(f"*工件*: `{ARTIFACT.relative_to(ROOT)}` · `generated_at = {meta['generated_at']}` · "
      f"`git_commit = {meta['git_commit']}` · 容差 `{tol:.0%}` · "
      f"地板规则 `e(n_max)/e(n_max/2) > {meta['floor_ratio_rule']}` · "
      f"阶次最少网格 {meta['min_grids_for_order']}")
    a("")
    a(f"*生成命令*: `{meta['command']}` · python {meta['python']} / numpy {meta['numpy']}")
    a("")

    # ---- A. case parameters and analytic reference values ----
    a("### A. 工况参数与解析基准（`tensorfvm.shallow_water.exact` 现场求值）")
    a("")
    a("| 工况 | `h_L`=`h0` [m] | `h_R`=`h1` [m] | `g` [m/s²] | 计算域 [m] | 坝位 `x_dam` [m] | "
      f"`t*` | `t` [s] |")
    a("|---|---:|---:|---:|---|---:|---:|---:|")
    for case in (RITTER_DRY, STOKER_WET):
        tt = t_star_to_time(case.t_star_end, case.h0, case.gravity)
        a(f"| `{case.key}` | {case.h0:.3f} | {case.h1:.3f} | {case.gravity:.2f} | "
          f"[{case.x_min:g}, {case.x_max:g}] | {case.x_dam:g} | {case.t_star_end:g} | "
          f"{tt:.6f} |")
    a("")
    a("| 参考量（`t* = %g`）| 工况 | 闭式值 |" % RITTER_DRY.t_star_end)
    a("|---|---|---:|")
    a(f"| 波前位置 `x_f(t)` [m] | `{RITTER_DRY.key}` | {x_ritter:.6f} |")
    a(f"| 水跃位置 `x_s(t)` [m] | `{STOKER_WET.key}` | {x_shock:.6f} |")
    a(f"| 涌后水位 `h2` [m] | `{STOKER_WET.key}` | {st['h2']:.9f} |")
    a(f"| 涌后流速 `u2` [m/s] | `{STOKER_WET.key}` | {st['u2']:.9f} |")
    a(f"| 水位阶跃 `h2/h1` [-] | `{STOKER_WET.key}` | {st['h2'] / st['h1']:.9f} |")
    a(f"| 水跃速度 `U` [m/s] | `{STOKER_WET.key}` | {st['shock_speed']:.9f} |")
    a("")

    # ---- B. convergence series ----
    for case, label in ((dry, "干床（Ritter）"), (wet, "湿床（Stoker）")):
        a(f"### B. {label}收敛序列 — headline = {case['quantity']}")
        a("")
        a("| n | dx [m] | `x_f(t)` 序列（验收量）| 可评样本 | headline | `depth_l1` | "
          "质量漂移 | 内部极值 | clipped | 判定 | wall [s] |")
        a("|---:|---:|---:|---:|---:|---:|---:|---:|---:|---|---:|")
        for r in case["rows"]:
            a(f"| {r['n']} | {r['dx']:.6g} | {_pct(r['front_series'])} | "
              f"{r['front_series_graded']}/{r['front_series_samples']} | "
              f"{_pct(r['headline'])} | {_pct(r['depth_l1'], 4)} | "
              f"{r['mass_drift']:.1e} | {r['local_extrema']} | {r['clipped_cells']} | "
              f"{'pass' if r['verdict_all_pass'] else ', '.join(r['verdict_failing'])} | "
              f"{r['wall_time_s']:.1f} |")
        a("")
        a(f"* 观测阶：`depth_l1` **{_order(case['observed_order_depth_l1'])}**、"
          f"`x_f(t)` 序列 **{_order(case['observed_order_series'])}**、"
          f"headline {_order(case['observed_order_headline'])}")
        a(f"* 逐级精化比 `e(n)/e(n/2)`：序列 {_ratios(case['series_decay'])}、"
          f"headline {_ratios(case['headline_decay'])}")
        a(f"* 序列最细一级比值 {case['series_decay']['finest_ratio']:.3f}"
          f"（地板规则 > {meta['floor_ratio_rule']} → "
          f"`at_floor = {case['series_decay']['at_floor']}`）")
        a(f"* accepted 网格（n ≥ {n_lo}）序列最大误差 "
          f"{_pct(case['series_max_over_accepted'])}，全部通过 {tol * 100:.0f} % 容差："
          f"`{case['all_accepted_pass']}`")
        if "bore_x_error" in case["rows"][0]:
            a(f"* 亚格 `bore_x` 观测阶 {_order(case['observed_order_bore_subcell'])}；"
              f"区段最大误差 {_pct(case['bore_max_cell_error_over_range'])}（格心负对照）")
        a("")

    # ---- C. data-driven (no-oracle) readings ----
    a("### C. 湿床无解析量读数（AUDIT F4 债务）在延伸网格上的复核")
    a("")
    a("| n | `bore_x` 亚格 | `bore_x_cell` 格心（负对照）| `h2` | 阶跃比 | `flatness` | "
      "`bore_valid` | `n_plateau` | 平台宽 [m] |")
    a("|---:|---:|---:|---:|---:|---:|---|---:|---:|")
    for r in wet["rows"]:
        a(f"| {r['n']} | {_pct(r['bore_x_error'], 4)} | {_pct(r['bore_x_cell_error'], 4)} | "
          f"{100.0 * r['bore_h2_error']:.3e} | {_pct(r['bore_step_ratio_error'], 4)} | "
          f"{_pct(r['bore_flatness'])} | {r['bore_valid']} | "
          f"{r.get('bore_n_plateau', '—')} | {_num(r.get('bore_plateau_width'), 3)} |")
    a("")
    a(f"* 格心负对照最细一级精化比 **{cell_ratio:.2f}**（> 1 即不随加密改善），"
      f"`bore_cell_decay.at_floor = {wet['bore_cell_decay']['at_floor']}`")
    a("")

    # ---- D. F9 ----
    a("### D. F9：无 oracle 平台检测器的扇/跳跃梯度比与切分穿点")
    a("")
    a(f"声明切分 `thresh = {cut:g} · max|dh/dx|`；`flatness > {flat_flag:g}` 时 "
      "`bore_valid = False`（振幅仍报出，评分方必须查该标志）。"
      "`fan_grad` 只在距最大梯度单元至少 `max(3 dx, 0.01 L)` 的上游区域取（物理半宽，"
      "避免跳跃抹平污染）。")
    a("")
    a("| n | `fan_grad` [m/m] | `jump_grad` [m/m] | `fan_over_jump` | < 切分？ | "
      "实际用切分 | `flatness` |")
    a("|---:|---:|---:|---:|---|---:|---:|")
    for r in wet["rows"]:
        a(f"| {r['n']} | {_num(r.get('fan_grad'))} | {_num(r.get('jump_grad'))} | "
          f"{r['fan_over_jump']:.3e} | {_yes(bool(r.get('fan_over_jump_below_cut')))} | "
          f"{r['bore_thresh_frac_used']:g} | {_pct(r['bore_flatness'])} |")
    a("")
    a("检测器实际走过的阶梯（`bore_attempts`；「未收紧是否可行」由它实测给出）：")
    a("")
    a("| n | 阶梯 | 结论 |")
    a("|---:|---|---|")
    for r in wet["rows"]:
        att = r.get("bore_attempts") or []
        cells = ", ".join(
            (f"{x['thresh_frac']:g}: bounded (n_plateau = {x['n_plateau']})"
             if x["bounded"] else f"{x['thresh_frac']:g}: unbounded") for x in att)
        tail = ("未收紧即 bounded" if att and att[0]["bounded"]
                else f"未收紧 **unbounded**；收紧后 delimit")
        a(f"| {r['n']} | {cells} | {tail} |")
    a("")
    a(f"* 扇/跳跃比由 {wet['rows'][0]['fan_over_jump']:.2e} 单调降到 "
      f"{wet['rows'][-1]['fan_over_jump']:.2e}；**首次低于切分 {cut:g} 的网格 = "
      f"`n = {fan_first}`**（未收紧读数在该网格 unbounded：`{not untightened_ok}`）。")
    a(f"* 阶梯在该网格用了 {decades_used} 个十进位（声明上限 "
      f"{PLATEAU_THRESH_MAX_DECADES}，剩余 {decades_left}），"
      f"救回后的 `bore_x` 误差 {_pct(wet_hi['bore_x_error'], 4)}、"
      f"`h2` 误差 {100.0 * wet_hi['bore_h2_error']:.3e}。")
    a("")
    a("历史记录（**不可由本仓库当前代码复跑**：修复已合入；数值出自本包首轮报告，"
      "此处保留以说明缺陷量级）：")
    a("")
    a("| 量 | 修前 `n = 3200` | 修前 `n = 6400` | 修后 `n = 6400`（本次实测）|")
    a("|---|---:|---:|---:|")
    a("| 平台 `h2` 相对误差 | 1.08e-4 | **15.53 %**（> 15 % 不可接受）| "
      f"{100.0 * wet_hi['bore_h2_error']:.3e} |")
    a("| 平台宽度 [m] | 3.01 | 5.88（真值 3.0）| "
      f"{_num(wet_hi.get('bore_plateau_width'), 3)} |")
    a("")

    # ---- E. guards + verdicts ----
    a("### E. 守卫与判定汇总")
    a("")
    a("| 判据 | 结果 |")
    a("|---|---|")
    a(f"| 全部网格的守恒/单调/正值守卫 | **{'PASS' if all_guard_pass else 'FAIL'}** |")
    a(f"| `x_f(t)` 序列 vs 闭式（accepted 网格，最大 {_pct(series_worst)} vs "
      f"容差 {tol * 100:.0f} %）| **{'PASS' if series_worst <= tol and dry['all_accepted_pass'] and wet['all_accepted_pass'] else 'FAIL'}** |")
    a(f"| 估计子地板（声明规则 > {meta['floor_ratio_rule']}）| "
      f"**{'FLOOR' if at_floor else 'NO-FLOOR'}** |")
    a(f"| F9 穿点防线 | **{'GUARDED' if (fan_first is None or untightened_ok is False) else 'UNGUARDED'}** |")
    mono = lambda vals: "单调下降" if _monotone(vals) else "**有回升（照实记录）**"
    a(f"| 序列误差单调性 | 干床 {mono([r['front_series'] for r in dry['rows']])} · "
      f"湿床 {mono([r['front_series'] for r in wet['rows']])} |")
    a(f"| `depth_l1` 单调性 | 干床 {mono([r['depth_l1'] for r in dry['rows']])} · "
      f"湿床 {mono([r['depth_l1'] for r in wet['rows']])} |")
    a("")

    # ---- F. per-quantity error judgement ----
    items = [
        ("Ritter `x_f(t)` 序列（验收量）", n_hi, dry_hi["front_series"]),
        ("Ritter `x_f(t)` 序列（验收量）", n_lo, dry_lo["front_series"]),
        ("Ritter headline `front_fan`", n_hi, dry_hi["headline"]),
        ("Stoker `x_f(t)` 序列（验收量）", n_hi, wet_hi["front_series"]),
        ("Stoker `x_f(t)` 序列（验收量）", n_lo, wet_lo["front_series"]),
        ("Stoker headline `shock_position`", n_hi, wet_hi["headline"]),
        ("Stoker `bore_x`（无解析量，亚格）", n_hi, wet_hi["bore_x_error"]),
        ("Stoker `h2`（无解析量）", n_hi, wet_hi["bore_h2_error"]),
        ("Stoker 阶跃比 `h2/h1`", n_hi, wet_hi["bore_step_ratio_error"]),
        ("Stoker `bore_x_cell`（负对照，不评分）", n_hi, wet_hi["bore_x_cell_error"]),
        ("Stoker `depth_l1`（格式精度量，看阶次）", n_hi, wet_hi["depth_l1"]),
        ("Ritter `depth_l1`（格式精度量，看阶次）", n_hi, dry_hi["depth_l1"]),
    ]
    a(f"### F. 关键量 vs 解析基准（逐项，显式回答是否 < "
      f"{STRICT_TOLERANCE * 100:.0f} %）")
    a("")
    a(f"| 关键量 | 网格 | 相对误差 | < {STRICT_TOLERANCE * 100:.0f} % ? | "
      f"< {tol * 100:.0f} %（锚点容差）? |")
    a("|---|---:|---:|---|---|")
    for label, n, val in items:
        a(f"| {label} | {n} | {'—' if val is None else _pct(val, 4)} | "
          f"{_yes(val is not None and val < STRICT_TOLERANCE)} | "
          f"{_yes(val is not None and val < tol)} |")
    graded = [it for it in items if "格式精度量" not in it[0] and "负对照" not in it[0]]
    strict_bad = [it for it in graded
                  if it[2] is None or not it[2] < STRICT_TOLERANCE]
    a("")
    a(f"* 被评分的 {len(graded)} 项中 **{len(graded) - len(strict_bad)} 项 < "
      f"{STRICT_TOLERANCE * 100:.0f} %**"
      + ("" if not strict_bad else "；不满足的是："
         + "、".join(f"{lab} @ n={n}（{_pct(v, 4)}）" for lab, n, v in strict_bad))
      + "。")
    a(f"* 两条 `depth_l1`（{_pct(dry_hi['depth_l1'], 4)} 干 / "
      f"{_pct(wet_hi['depth_l1'], 4)} 湿）**不设 {STRICT_TOLERANCE * 100:.0f} % 目标**：解含间断，"
      f"L1 理论上一阶收敛，判定看阶次（{_order(dry['observed_order_depth_l1'])} / "
      f"{_order(wet['observed_order_depth_l1'])}）而不是绝对值。")
    a(f"* 负对照 `bore_x_cell` 在 `n = {res[-2]} → {n_hi}` 由 "
      f"{_pct(_row_by_n(wet, res[-2])['bore_x_cell_error'], 4)} 变为 "
      f"{_pct(wet_hi['bore_x_cell_error'], 4)}（精化比 {cell_ratio:.2f}），"
      "即使数值小也不构成收敛证据，故不参与判定。")
    a("")
    a(END)
    return "\n".join(L)


# --------------------------------------------------------------------------- #
# REPORT.md assembly / drift gate
# --------------------------------------------------------------------------- #
def splice(report_text: str, block: str) -> str:
    """Replace the marked block in ``report_text`` (or append it if absent)."""
    i = report_text.find(BEGIN)
    j = report_text.find(END)
    if i < 0 or j < 0 or j < i:
        sep = "" if report_text.endswith("\n") else "\n"
        return report_text + sep + "\n" + block + "\n"
    return report_text[:i] + block + report_text[j + len(END):]


def load_report() -> str:
    if not REPORT.exists():
        raise SystemExit(f"{REPORT} does not exist")
    return REPORT.read_text()


def publish_markdown(block: str) -> str:
    """Platform report body: the rendered block plus a short header."""
    return "\n".join([
        "## 1. 案例介绍",
        "浅水方程一维溃坝：Ritter 干床（h0 = 1, h1 = 0）与 Stoker 湿床"
        "（h0 = 1, h1 = 0.5），g = 9.81 m/s²，坝位于 x = 0，t* = t·√(g/h0) = 2。"
        "格式：有限体积 + MUSCL(minmod) + HLL + SSP-RK3，CFL 0.4，反射壁。"
        "本包把已发表证据由 n ≤ 1600 延伸到 n = 6400（AUDIT §1 的『未运行』欠账），"
        "并把无解析量平台检测器的网格依赖缺陷 F9 定位到具体网格。",
        "",
        "## 2. 怎么做的",
        "`scripts/run_shallow_water_dam_break_hires.py` 逐网格运行 `run_case`，记录验收量"
        "（整条 x_f(t) 序列最大相对误差与分级样本数）、headline@t*=2、湿床无解析量亚格"
        "读数与格心负对照、depth L1、守恒/单调守卫、verdict 全部失败键，以及新增的 "
        "F9 诊断（扇/跳跃梯度比、检测器实际走过的切分阶梯）。判定规则先验写死，事后才看数。"
        "以下全部数字由 `publish_report.py` 从 hires.json 程序化渲染（零手抄）。",
        "",
        "## 3. 计算结果",
        block,
        "",
        "## 4. 结果图",
        "`hires_convergence.png`：两工况误差 vs dx（双对数，含一阶/二阶参考线与容差线）"
        "与逐级误差比值 vs 地板规则。`profiles.png`：t* = 2 最细网格的深度剖面 h(x) "
        "数值 vs 闭式解（上排全域、下排干床波前 / 湿床水跃放大）。",
        "",
        "## 5. 注意点",
        "* F9 是**有条件通过**：穿点处靠已声明的十进位重试阶梯救回，阶梯用尽后检测器按设计"
        "整体失效（`plateau_unbounded`，全 NaN），届时必须先改判据再上网格。",
        "* `fan_grad` 的排除窗口必须是**物理半宽**；只用固定单元数窗口时细网格会被跳跃抹平"
        "污染，诊断会假报“比值仍在切分之上”。",
        "* `x_f(t)` 序列的观测阶显著低于一阶：该量由波前读数估计子主导，故本包只主张 "
        "`depth_l1` 的一阶，不主张序列阶次。",
        "* 5 % 门在 n ≥ 3200 上几乎无判决力（误差已降两个数量级），属回归防护而非精度标定。",
        "* n = 12800 只有合成解析剖面复核，求解器未跑：**未运行项**，不是通过项。",
        "",
        "## 6. 误差判定",
        "见数据块 F 节：逐项列出相对误差并显式回答是否 < 3 %；两条 `depth_l1` 与负对照"
        "`bore_x_cell` 显式声明不参与该判定及原因。",
    ])


# --------------------------------------------------------------------------- #
# platform publishing (kept from the first round of this package)
# --------------------------------------------------------------------------- #
def _post(path: str, payload: dict, token: str | None = None) -> dict:
    headers = {"Content-Type": "application/json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    req = urllib.request.Request(BASE.rstrip("/") + path,
                                 data=json.dumps(payload).encode(), headers=headers,
                                 method="POST")
    with urllib.request.urlopen(req, timeout=120) as rsp:
        return json.loads(rsp.read().decode())


def login() -> str:
    data = _post("/api/v1/auth/login", {"username": USER, "password": PASS})
    return data.get("access_token") or data.get("token") or ""


def _figure(path: Path, caption: str) -> dict | None:
    if not path.exists():
        return None
    return {"name": path.name, "caption": caption,
            "png_base64": base64.b64encode(path.read_bytes()).decode()}


def report_body(payload: dict, block: str, mission_id: int) -> dict:
    """The platform report payload (shared by --publish and the curl workflow)."""
    dry = payload["cases"][RITTER_DRY.key]
    wet = payload["cases"][STOKER_WET.key]
    res = payload["meta"]["resolutions"]
    figures = [f for f in (
        _figure(CONVERGENCE_FIG,
                "CASE-FVM-DAMBREAK-STOKER 高分辨率延伸：误差 vs dx（含一阶/二阶参考线"
                "与容差线）与逐级误差比值 vs 声明的地板规则"),
        _figure(PROFILE_FIG,
                "t* = 2 最细网格深度剖面 h(x) 数值 vs 闭式解（全域 + 干床波前/湿床水跃放大）"),
    ) if f]
    body = {
        "title": (f"CASE-FVM-DAMBREAK-STOKER 高分辨率延伸（n = {res[0]}…{res[-1]}）："
                  "误差收敛性、估计子地板与 F9 切分穿点"),
        "summary": (f"溃坝 Ritter/Stoker 延伸至 n = {res[-1]}：depth L1 观测阶 "
                    f"{dry['observed_order_depth_l1']:.2f}(干)/"
                    f"{wet['observed_order_depth_l1']:.2f}(湿)，验收量 x_f(t) 序列最细 "
                    f"{100 * dry['rows'][-1]['front_series']:.2f}%/"
                    f"{100 * wet['rows'][-1]['front_series']:.2f}% 且未到估计子地板；"
                    f"无解析量检测器的扇/跳跃梯度比在 n = "
                    f"{wet.get('fan_over_jump_first_below_cut')} 穿过声明的切分，"
                    "重试阶梯实测救回平台读数（有条件通过）"),
        "scenario_key": "case-fvm-dambreak-stoker-hires",
        "mission_id": mission_id,
        "tags": ["TensorFVM", "shallow-water", "dam-break", "Ritter", "Stoker",
                 "verification", "grid-convergence", "estimator-floor", "F9"],
        "markdown": publish_markdown(block),
        "figures": figures,
    }
    return body


def publish(payload: dict, block: str, mission_id: int) -> dict:
    body = report_body(payload, block, mission_id)
    return _post("/api/v1/tensor/reports", body, login())


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--artifact", default=str(ARTIFACT))
    ap.add_argument("--report", default=str(REPORT))
    ap.add_argument("--check", action="store_true",
                    help="fail if the committed block is stale (drift gate)")
    ap.add_argument("--stdout", action="store_true", help="print the block, write nothing")
    ap.add_argument("--publish", action="store_true",
                    help="post the rendered report to the platform")
    ap.add_argument("--mission-id", type=int, default=23156)
    ap.add_argument("--emit-report", default=None,
                    help="write the platform report payload (JSON) to this path")
    args = ap.parse_args(argv)

    payload = load_payload(Path(args.artifact))
    block = render_block(payload)
    report_path = Path(args.report)

    if args.stdout:
        print(block)
        return 0

    if args.check:
        current = report_path.read_text()
        expected = splice(current, block)
        if current != expected:
            print(f"CHECK FAILED: {report_path} data block is stale; regenerate with "
                  f"`publish_report.py`", file=sys.stderr)
            return 1
        print(f"CHECK OK: {report_path} data block matches the artefact "
              f"({block.count(chr(10))} lines)")
        return 0

    updated = splice(report_path.read_text(), block)
    report_path.write_text(updated)
    print(f"updated {report_path} ({len(updated)} chars) from {args.artifact}")

    if args.emit_report:
        Path(args.emit_report).write_text(
            json.dumps(report_body(payload, block, args.mission_id)))
        print(f"wrote {args.emit_report}")

    if args.publish:
        rsp = publish(payload, block, args.mission_id)
        print("published:", json.dumps(rsp, ensure_ascii=False)[:400])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())